package java_problems.hard.p2472;

import java_problems.SolutionTestBase;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.stream.Stream;

@DisplayName("2472. Maximum Number of Non-overlapping Palindrome Substrings")
class SolutionTest extends SolutionTestBase {

    static Stream<Arguments> provideData() {
        return Stream.of(

                Arguments.of("abcacbaab", 3, 2),

                Arguments.of("abaccdbbd", 3, 2),
                Arguments.of("adbcda", 2, 0),

                Arguments.of("fttfjofpnpfydwdwdnns", 2, 4),
                Arguments.of("", 2, 1000),
                Arguments.of("sjbxiufnaanqkwsqswkqrcznzcddhtuhtthuttjfuufjtcfywgecegwyhhnnhtozczirynhhnyrire", 3, 10),
                Arguments.of("", 4, 44)

        );
    }

    @ParameterizedTest
    @MethodSource("provideData")
    void solutionTest(String s, int k, int expected) {
        Assertions.assertEquals(expected, new Solution().maxPalindromes(s, k));
    }

}